import React from 'react';
import { defaultEventConfig } from '../config/eventConfig';

// 공통 Select 컴포넌트
function Select({ label, name, options, value, onChange }) {
  return (
    <div className="mb-4">
      <label className="block text-sm font-medium mb-1">{label}</label>
      <select
        name={name}
        value={value}
        onChange={e => onChange(name, e.target.value)}
        className="w-full border p-2 rounded-md"
      >
        {options.map(opt => (
          <option key={opt.value} value={opt.value}>{opt.label}</option>
        ))}
      </select>
    </div>
  );
}

export default function EventSalesInputForm({ values, onChange, others, recommendedDiscount }) {
  const { devices } = defaultEventConfig;
  const selectedDevice = devices.find(d => d.id === values.deviceModel);

  return (
    <>
      {/* 단말기 모델 선택 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">단말기 모델</label>
        <select
          name="deviceModel"
          value={values.deviceModel}
          onChange={e => onChange('deviceModel', e.target.value)}
          className="w-full border p-2 rounded-md"
        >
          <option value="">모델을 선택하세요</option>
          {devices.map(device => (
            <option key={device.id} value={device.id}>{device.name}</option>
          ))}
        </select>
      </div>

      {/* 메모리 옵션 */}
      {selectedDevice && (
        <div className="mb-4">
          <label className="block text-sm font-medium mb-1">메모리 옵션</label>
          <select
            name="deviceVariant"
            value={values.deviceVariant}
            onChange={e => {
              onChange('deviceVariant', e.target.value);
              const variant = selectedDevice.variants.find(v => v.id === e.target.value);
              onChange('devicePrice', variant ? variant.price : '');
            }}
            className="w-full border p-2 rounded-md"
          >
            <option value="">용량을 선택하세요</option>
            {selectedDevice.variants.map(v => (
              <option key={v.id} value={v.id}>{v.memory}</option>
            ))}
          </select>
        </div>
      )}

      {/* 단말기 출고가 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">단말기 출고가</label>
        <input
          type="text"
          name="devicePrice"
          value={values.devicePrice ? `${values.devicePrice.toLocaleString()}원` : ''}
          readOnly
          className="w-full border p-2 rounded-md bg-gray-100"
          placeholder="출고가가 자동 표시됩니다"
        />
      </div>

      {/* 추가 혜택 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">추가 혜택</label>
        <div className="w-full border p-2 rounded-md bg-gray-50 text-sm whitespace-pre-wrap">
          {others || '선택된 요금제의 혜택 정보가 없습니다.'}
        </div>
      </div>

      {/* 할인 선택 */}
      <Select
        label="할인 선택"
        name="discountType"
        options={[
          { value: '', label: '할인 없음' },
          { value: 'contract', label: '요금할인 (25%)' },
          { value: 'subsidy', label: '공시 지원금' }
        ]}
        value={values.discountType}
        onChange={onChange}
      />
      {recommendedDiscount && (
        <p className="mt-1 text-sm text-blue-600">추천 할인: {recommendedDiscount}</p>
      )}

      {/* 공시 지원금 금액 입력 */}
      {values.discountType === 'subsidy' && (
        <div className="mb-4">
          <label className="block text-sm font-medium mb-1">공시 지원금 금액</label>
          <input
            type="number"
            name="subsidyAmount"
            value={values.subsidyAmount || ''}
            onChange={e => onChange('subsidyAmount', e.target.value)}
            className="w-full border p-2 rounded-md"
            placeholder="지원금 금액을 입력하세요"
          />
        </div>
      )}

      {/* 부분 수납 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">부분 수납</label>
        <input
          type="number"
          name="partialPayment"
          value={values.partialPayment || ''}
          onChange={e => onChange('partialPayment', e.target.value)}
          className="w-full border p-2 rounded-md"
          placeholder="부분 수납 입력"
        />
      </div>

      {/* 5G 시니어 카테고리 일 때 기초연금 선택 */}
      {values.category === '5G 시니어 (만 65세 이상)' && (
        <Select
          label="기초연금 수급 여부"
          name="pensionApply"
          options={[
            { value: '', label: '— 선택하세요 —' },
            { value: 'yes', label: '기초연금 수급 적용' },
            { value: 'no', label: '기초연금 수급 미적용' }
          ]}
          value={values.pensionApply}
          onChange={onChange}
        />
      )}

      {/* 할부개월 */}
      <Select
        label="할부개월"
        name="installments"
        options={[6, 12, 24, 36].map(n => ({ value: n, label: `${n}개월` }))}
        value={values.installments}
        onChange={onChange}
      />
    </>
  );
}
