import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import EventSalesFilterForm from './EventSalesFilterForm';
import EventSalesInputForm from './EventSalesInputForm';
import EventSalesResult from './EventSalesResult';
import { phonePlans } from '../config/phonePlanConfig';
import { defaultEventConfig } from '../config/eventConfig';
import SaveConsultationButton from '../components/SaveConsultationButton';  // 상담 저장 및 공유 버튼 컴포넌트

export default function EventSalesCalculator() {
  const navigate = useNavigate();
  const [values, setValues] = useState({
    dataFilter: '',
    category: '',
    planId: '',
    planCost: 0,
    others: '',
    deviceModel: '',
    deviceVariant: '',
    discountType: '',
    partialPayment: 0,
    subsidyAmount: 0,
    installments: 24,
    pensionApply: '',
  });
  const [result, setResult] = useState(null);
  const [recommendedDiscount, setRecommendedDiscount] = useState('');
  const monthlyRate = 0.059 / 12;

  const handleFilterChange = (name, value) => {
    setValues(prev => ({
      ...prev,
      [name]: value,
      ...(name === 'planId' && {
        planCost: phonePlans.find(p => p.id === value)?.monthlyFee || 0,
        others: phonePlans.find(p => p.id === value)?.others || ''
      }),
      ...(name === 'category' && { pensionApply: '' }),
      ...(name === 'dataFilter' && { category: '', planId: '', planCost: 0 })
    }));
    setResult(null);
    setRecommendedDiscount('');
  };

  const handleInputChange = (name, value) => {
    setValues(prev => ({
      ...prev,
      [name]: ['partialPayment','subsidyAmount','installments'].includes(name) ? Number(value) : value
    }));
    setResult(null);
    setRecommendedDiscount('');
  };

  const isSenior = values.category === '5G 시니어 (만 65세 이상)';
  const hasPension = values.pensionApply === 'yes';

  const canCalc =
    values.planCost > 0 &&
    values.deviceModel &&
    values.deviceVariant &&
    values.discountType &&
    (!isSenior || values.pensionApply);

  const handleCalculate = () => {
    if (!canCalc) return;
    const { planCost, deviceModel, deviceVariant, discountType, partialPayment, subsidyAmount, installments } = values;
    // 기초연금 할인액 계산
    const pensionDiscount = isSenior && hasPension ? Math.min(planCost * 0.5, 12100) : 0;
    // 단말 원금
    const basePrice = defaultEventConfig.devices.find(d => d.id === deviceModel)?.variants.find(v => v.id === deviceVariant)?.price || 0;
    const principal = basePrice - partialPayment;
    const principalAfterSubsidy = principal - subsidyAmount;
    // 단말 할부
    const deviceCostContract = installments > 0 ? Math.ceil((principal * monthlyRate)/(1-Math.pow(1+monthlyRate,-installments))) : 0;
    const deviceCostSubsidy = installments > 0 ? Math.ceil((principalAfterSubsidy * monthlyRate)/(1-Math.pow(1+monthlyRate,-installments))) : 0;
    // 요금제 비용
    const rawContractPlan = planCost * 0.75;
    const rawSubsidyPlan = planCost;
    // 총합 시나리오
    const totalContractBase = rawContractPlan + deviceCostContract - pensionDiscount;
    const totalSubsidyBase = rawSubsidyPlan + deviceCostSubsidy;
    // 실제 선택 결과
    const monthlyPlanCost = planCost;
    const deviceInstallment = discountType === 'contract' ? deviceCostContract : deviceCostSubsidy;
    const totalPayment = discountType === 'contract' ? totalContractBase : totalSubsidyBase;
    // 절감액 계산
    const savings = discountType === 'contract'
      ? pensionDiscount
      : totalContractBase - totalSubsidyBase;
    const recommended = totalContractBase < totalSubsidyBase ? '요금할인' : '공시 지원금';
    setResult({ monthlyPlanCost, deviceInstallment, totalPayment, savings, pensionDiscount });
    setRecommendedDiscount(recommended);
  };

  return (
    <div className="flex justify-center bg-gray-100 p-4 min-h-screen items-start pt-8">
      <div className="w-full max-w-lg bg-white rounded-lg shadow-lg p-6">
        <h1 className="text-2xl font-bold mb-2 text-center">KT 이벤트 계산기</h1>
        <p className="text-center text-red-600 text-sm mb-4">주의! 본 견적은 가 견적이오니, 정확한 견적은 필히 추가로 확인하셔야 합니다.</p>
        <EventSalesFilterForm values={values} onChange={handleFilterChange} />
        <EventSalesInputForm values={values} onChange={handleInputChange} recommendedDiscount={recommendedDiscount} />
        {isSenior && (
          <div className="mb-4">
            <label className="block text-sm font-medium mb-1">기초연금 수급 여부</label>
            <select name="pensionApply" value={values.pensionApply} onChange={e => handleInputChange('pensionApply', e.target.value)} className="w-full border p-2 rounded-md">
              <option value="">— 선택하세요 —</option>
              <option value="yes">기초연금 수급 적용</option>
              <option value="no">기초연금 수급 미적용</option>
            </select>
          </div>
        )}
        <button type="button" onClick={handleCalculate} disabled={!canCalc} className={`w-full bg-blue-600 text-white py-2 rounded-md mb-4 hover:bg-blue-700 transition ${!canCalc ? 'opacity-50 cursor-not-allowed' : ''}`}>계산하기</button>
        {result && <EventSalesResult
          monthlyPlanCost={result.monthlyPlanCost}
          deviceInstallment={result.deviceInstallment}
          totalPayment={result.totalPayment}
          savings={result.savings}
          appliedPensionDiscount={result.pensionDiscount}
          discountType={values.discountType}
          pensionApply={values.pensionApply}
        />
        }
               {/* 이 부분이 “상담 저장하기 및 공유” 버튼 */}   
               <div className="mt-4">
               <SaveConsultationButton formData={values} />
               </div>  
        <button type="button" onClick={() => navigate('/')} className="w-full bg-gray-200 text-gray-700 py-2 rounded-lg mt-2 hover:bg-gray-300">
        메인 메뉴로 돌아가기</button>
      </div>
    </div>
  );
}
